 "<div style=\"background:#ffffff;color:#222;padding:10px 6px 12px;font-size:14px;line-height:1.3\"><b>Mostaza</b><br>#F6C445</div>": "<div style=\"background:#ffffff;color:#222;padding:10px 6px 12px;font-size:14px;line-height:1.3\"><b>Mosterd</b><br>#F6C445</div>",
 "<div style=\"background:#ffffff;color:#222;padding:10px 6px 12px;font-size:14px;line-height:1.3\"><b>Hoja</b><br>#4CAF7D</div>": "<div style=\"background:#ffffff;color:#222;padding:10px 6px 12px;font-size:14px;line-height:1.3\"><b>Blad</b><br>#4CAF7D</div>",
