 "<span style=\"font-family:'Playfair Display', serif;font-size:28px\">Clásica</span>  <span style=\"color:#666666\">Playfair Display / Lato</span>": "<span style=\"font-family:'Playfair Display', serif;font-size:28px\">Klassiek</span>  <span style=\"color:#666666\">Playfair Display / Lato</span>",
